	zip.Describe("github.com/hanzoai/cloud/apps/social POST /v1/social/posts", zip.Doc{
		Description: "Stores a post for the org and answers 201 with the stored row.\n\nA post created as scheduled for a time that has already passed is published\nIMMEDIATELY, and the row returned carries that outcome — this is the one behaviour\na reader would otherwise miss. A future-scheduled post is left for the scheduler,\nand a draft is left alone. Publishing never fails the creation: the post is stored\neither way, and a publish that could not run leaves the row for the scheduler to\nretry.",
		Fields: map[string]string{
			"socialPost.accountId":             "AccountID / ExternalID / Error are server-managed publish results, set only by\nthe publish path (never by a client update): the account a post was published\nthrough, the provider's returned external post id (for reconciliation), and the\nlast failure reason. Empty until a publish attempt lands.\nAccountID is the connected account the post went out through. Absent until\na publish succeeds.",
			"socialPost.channel":               "Channel is the network this post targets: x, facebook, instagram, linkedin,\ntiktok, youtube or threads. It is the channel whose CONNECTED accounts a\npublish fans out to.\n\nExample: \"x\"",
			"socialPost.content":               "Content is the post's text, bounded at 8192 characters.\n\nExample: \"Shipping today.\"",
			"socialPost.createdAt":             "CreatedAt is when the post was created, as a unix timestamp in seconds.",
			"socialPost.error":                 "Error is why the last publish attempt failed, verbatim and bounded. Absent\nwhen no attempt has failed; cleared by a later success. A post published to\nseveral accounts that only some took is published, and this names the rest.",
			"socialPost.externalGroup":         "ExternalGroup is the Postiz group the post belongs to (optional).",
			"socialPost.externalId":            "ExternalID is the id the network returned for the published post, which is\nwhat reconciles this row against the post on the network. Absent until a\npublish succeeds.",
			"socialPost.externalIdPostiz":      "ExternalIDPostiz is the Postiz post id, set only for origin=postiz rows.",
			"socialPost.externalIntegrationId": "ExternalIntegrationId is the Postiz integration id that published it.",
			"socialPost.id":                    "ID is the post's identifier, minted on create and the id every later call\naddresses it by.\n\nExample: \"post_91ab20\"",
			"socialPost.media":                 "Media is the post's attached media as a list of URLs (images today; the\ncomposer's URL field now, an S3 picker later, populate it). Stored as a JSON\narray in the media TEXT column and ALWAYS serialized as an array (never null),\nso a client can rely on `media` being present. Bounded at the write layer\n(normMedia in social.go): each URL clipped to maxField, the list to maxMedia.",
			"socialPost.origin":                "Origin is who owns the post: \"native\" (a Hanzo user created it) or\n\"postiz\" (mirrored from Postiz via ingest/poller). Mirrored posts are\nread-only — clients may not create, update, publish or schedule them.",
			"socialPost.releaseUrl":            "ReleaseURL is the live URL Postiz returned for the published post.",
			"socialPost.scheduleAt":            "ScheduleAt is when the post is due, as a unix timestamp in SECONDS. 0 means\nunscheduled. It is meaningful only while the status is scheduled — a\nscheduled post whose time has arrived is published by the scheduler.",
			"socialPost.status":                "Status is the post's lifecycle state: draft, scheduled, published or failed.\nA fifth, transient publishing state exists while a publish attempt holds the\nclaim; it is never settable from a request and a caller sees it only if it\nreads a post mid-attempt.",
			"socialPost.updatedAt":             "UpdatedAt is when the post row last changed, as a unix timestamp in seconds.\nThe listing is ordered by it, newest first.",
			"socialPostBody.channel":           "Channel is the network to publish to: x, facebook, instagram, linkedin,\ntiktok, youtube or threads. Omitted means x.\n\nExample: \"x\"",
			"socialPostBody.content":           "Content is the post's text. Required — an empty body is a 400 — and bounded\nat 8192 characters, comfortably above every network's own limit.\n\nExample: \"Shipping today.\"",
			"socialPostBody.media":             "Media is the post's attached media as URLs, at most 10, each bounded at 1024\ncharacters. Blank entries are dropped. Omitting it CLEARS any stored media.",
			"socialPostBody.scheduleAt":        "ScheduleAt is when to publish, as a unix timestamp in SECONDS. 0 means\nunscheduled. A negative value is clamped to 0. It only matters for a post\nwhose status is scheduled.",
			"socialPostBody.status":            "Status is the post's lifecycle state: draft, scheduled, published or failed.\nOmitted means draft. The transient publishing claim is never settable here —\naccepting it from a request would let a caller wedge or replay the guard that\nstops two publishers double-posting the same row.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/social POST /v1/social/posts/:id/publish", zip.Doc{
		Description: "Publishes the post immediately to the connected accounts on its channel\nand answers with the updated row, carrying the account and external id it\npublished under.\n\nIt is IDEMPOTENT: a post that has already published, or that another caller is\npublishing right now, comes back unchanged rather than being posted twice. That\nclaim is taken before any network call, which is what makes a double submit safe.\n\nThe two failure shapes differ on purpose. Having no connected account for the\nchannel is the caller's to fix, so it is recorded ON the post as failed with the\nreason and answers normally. A deployment that lacks the network's own credentials\ncannot publish for anyone, so that is a 503 naming exactly what is missing.",
		Fields: map[string]string{
			"rowRef.id":                        "ID is the account or post to act on, taken from the path.",
			"socialPost.accountId":             "AccountID / ExternalID / Error are server-managed publish results, set only by\nthe publish path (never by a client update): the account a post was published\nthrough, the provider's returned external post id (for reconciliation), and the\nlast failure reason. Empty until a publish attempt lands.\nAccountID is the connected account the post went out through. Absent until\na publish succeeds.",
			"socialPost.channel":               "Channel is the network this post targets: x, facebook, instagram, linkedin,\ntiktok, youtube or threads. It is the channel whose CONNECTED accounts a\npublish fans out to.\n\nExample: \"x\"",
			"socialPost.content":               "Content is the post's text, bounded at 8192 characters.\n\nExample: \"Shipping today.\"",
			"socialPost.createdAt":             "CreatedAt is when the post was created, as a unix timestamp in seconds.",
			"socialPost.error":                 "Error is why the last publish attempt failed, verbatim and bounded. Absent\nwhen no attempt has failed; cleared by a later success. A post published to\nseveral accounts that only some took is published, and this names the rest.",
			"socialPost.externalGroup":         "ExternalGroup is the Postiz group the post belongs to (optional).",
			"socialPost.externalId":            "ExternalID is the id the network returned for the published post, which is\nwhat reconciles this row against the post on the network. Absent until a\npublish succeeds.",
			"socialPost.externalIdPostiz":      "ExternalIDPostiz is the Postiz post id, set only for origin=postiz rows.",
			"socialPost.externalIntegrationId": "ExternalIntegrationId is the Postiz integration id that published it.",
			"socialPost.id":                    "ID is the post's identifier, minted on create and the id every later call\naddresses it by.\n\nExample: \"post_91ab20\"",
			"socialPost.media":                 "Media is the post's attached media as a list of URLs (images today; the\ncomposer's URL field now, an S3 picker later, populate it). Stored as a JSON\narray in the media TEXT column and ALWAYS serialized as an array (never null),\nso a client can rely on `media` being present. Bounded at the write layer\n(normMedia in social.go): each URL clipped to maxField, the list to maxMedia.",
			"socialPost.origin":                "Origin is who owns the post: \"native\" (a Hanzo user created it) or\n\"postiz\" (mirrored from Postiz via ingest/poller). Mirrored posts are\nread-only — clients may not create, update, publish or schedule them.",
			"socialPost.releaseUrl":            "ReleaseURL is the live URL Postiz returned for the published post.",
			"socialPost.scheduleAt":            "ScheduleAt is when the post is due, as a unix timestamp in SECONDS. 0 means\nunscheduled. It is meaningful only while the status is scheduled — a\nscheduled post whose time has arrived is published by the scheduler.",
			"socialPost.status":                "Status is the post's lifecycle state: draft, scheduled, published or failed.\nA fifth, transient publishing state exists while a publish attempt holds the\nclaim; it is never settable from a request and a caller sees it only if it\nreads a post mid-attempt.",
			"socialPost.updatedAt":             "UpdatedAt is when the post row last changed, as a unix timestamp in seconds.\nThe listing is ordered by it, newest first.",
		},
	})
