	zip.Describe("github.com/hanzoai/cloud/apps/social PUT /v1/social/accounts/:id", zip.Doc{
		Description: "Replaces the account's network, handle and status with what the\nbody carries, and answers with the stored row.\n\nThis is a REPLACEMENT, not a merge, which is the rule most easily got wrong: a\nfield the body omits is written as its default, so leaving out the handle blanks\nit and leaving out the status resets it to connected. Send the whole record. The\nsame vocabularies as create apply, and an unknown network or status is refused\nrather than coerced.",
		Fields: map[string]string{
			"socialAccount.createdAt":     "CreatedAt is when the account was connected, as a unix timestamp in seconds.",
			"socialAccount.disabled":      "Disabled is true when posting to this channel has been paused without\ndisconnecting its stored credentials.",
			"socialAccount.externalId":    "ExternalID is the platform id the sealed token is stored under. Empty for\nan account recorded by hand, before a consent named one. A publish uses\nit to choose that token rather than another account on the same network.",
			"socialAccount.groupId":       "GroupID is the deterministic identifier of the employee or brand channel\ngroup this channel is organized under. Optional.",
			"socialAccount.groupName":     "GroupName is the employee or brand group label (for example \"Antje Worring\",\n\"Zach Kelling\", or \"Hanzo AI\") used to organize and fan out posts across a\nperson's or team's channels. Optional.",
			"socialAccount.handle":        "Handle is the account's public name on the network, as the customer knows\nit. Trimmed and bounded at 1024 characters.\n\nExample: \"@acme\"",
			"socialAccount.id":            "ID is the account's identifier, minted on connect and the id every later\ncall addresses it by.\n\nExample: \"acct_7f3c1a\"",
			"socialAccount.name":          "Name is the channel's human-readable display name on the network (for\nexample \"Antje Worring\" or \"Hanzo AI\"). Optional.",
			"socialAccount.picture":       "Picture is the avatar URL of the connected channel profile, when reported\nby the network. Optional.",
			"socialAccount.profile":       "Profile is the canonical profile identifier or URL slug on the network.\nOptional.",
			"socialAccount.provider":      "Provider is the network this account is on: x, facebook, instagram,\nlinkedin, tiktok, youtube or threads.\n\nExample: \"x\"",
			"socialAccount.refreshNeeded": "RefreshNeeded is true when the upstream OAuth token has expired or requires\ninteractive reconnection before publishing.",
			"socialAccount.status":        "Status is the connection lifecycle: connected, disconnected or error. Only\na connected account is a publish target.",
			"socialAccount.updatedAt":     "UpdatedAt is when the account row last changed, as a unix timestamp in\nseconds. The listing is ordered by it, newest first.",
			"socialAccountWrite.handle":   "Handle is the account's public name on the network. Omitting it BLANKS the\nstored handle: this is a replacement, not a merge.\n\nExample: \"@acme\"",
			"socialAccountWrite.provider": "Provider is the network this account is on: x, facebook, instagram, linkedin,\ntiktok, youtube or threads. Omitted means x.\n\nExample: \"x\"",
			"socialAccountWrite.status":   "Status is the connection lifecycle: connected, disconnected or error.\nOmitting it RESETS the account to connected.",
		},
	})
